head.b:skin:
/* ---------------------------------------------------------------------------------------
[STEPS 1-10] TITAN CORE DESIGN SYSTEM - PRODUCTION AUDIT v43.0
--------------------------------------------------------------------------------------- */
:root {
    --primary: #ce1212; --primary-dark: #a00d0d;
    --secondary: #37373f; --accent: #ffc107;
    --bg-body: #f8f9fa; --bg-card: #ffffff;
    --text-main: #1d1d1f; --text-muted: #86868b;
    --font-main: "Inter", sans-serif; --font-accent: "Amatic SC", sans-serif;
    --font-mono: "JetBrains Mono", monospace;
    --transition: 0.4s cubic-bezier(0.165, 0.84, 0.44, 1);
    --z-navbar: 1030; --z-mobile-nav: 1050; --z-toast: 1100;
    --shadow-sm: 0 4px 12px rgba(0,0,0,0.03);
    --shadow-lg: 0 20px 60px rgba(0,0,0,0.08);
    --radius-xl: 24px;
}

[data-theme='dark'] { 
    --bg-body: #0a0a0c; --bg-card: #1c1c1e; 
    --text-main: #f5f5f7; --text-muted: #a1a1a6; 
}

/* [FLUID TYPOGRAPHY LOGIC] - Prevents Truncation */
h1, .display-1 { font-size: clamp(2.2rem, 6vw, 4rem); line-height: 1.1; font-weight: 800; letter-spacing: -1.5px; }
h2, .display-2 { font-size: clamp(1.8rem, 5vw, 3.2rem); font-weight: 700; }
h4, .product-card h4 { font-size: clamp(1rem, 2.5vw, 1.25rem) !important; line-height: 1.4; font-weight: 700; }
.lead { font-size: clamp(0.95rem, 2vw, 1.15rem); line-height: 1.6; }

/* [STEP 94] CLEAN AUDIT PERFORMANCE */
body { font-family: var(--font-main); background: var(--bg-body); color: var(--text-main); padding-top: 85px; padding-bottom: 95px; transition: background 0.3s; overflow-x: hidden; -webkit-font-smoothing: antialiased; }
body.rtl { direction: rtl; text-align: right; }

#scroll-fill { position: fixed; top: 0; left: 0; height: 4px; background: var(--primary); z-index: 2100; width: 0%; transition: 0.1s; box-shadow: 0 0 15px var(--primary); }

.breadcrumb-flat { font-size: 0.65rem; font-weight: 800; text-transform: uppercase; color: var(--text-muted); margin-bottom: 25px; letter-spacing: 1.2px; display: flex; align-items: center; flex-wrap: wrap; }
.breadcrumb-flat a { color: var(--primary); text-decoration: none; }
.breadcrumb-flat span { margin: 0 10px; opacity: 0.3; }

/* [STEP 86/97] GRID ARCHITECTURE - MOBILE 1-COL FORCED */
.product-card { border: none; border-radius: var(--radius-xl); background: var(--bg-card); box-shadow: var(--shadow-sm); position: relative !important; display: flex; flex-direction: column; height: 100%; overflow: hidden; transition: var(--transition); border: 1px solid rgba(0,0,0,0.02); }
.product-card:hover { transform: translateY(-10px); box-shadow: var(--shadow-lg); }

.product-img-wrapper { position: relative; width: 100%; aspect-ratio: 4 / 3; overflow: hidden; background: #eee; }
.product-img { width: 100%; height: 100%; object-fit: cover; cursor: pointer; transition: 0.8s ease; }

@media (max-width: 576px) { 
    .product-grid-item { width: 100% !important; flex: 0 0 100% !important; max-width: 100% !important; margin-bottom: 30px !important; }
    .product-img-wrapper { aspect-ratio: 1 / 1 !important; } 
    .product-card h4 { font-size: 1.4rem !important; }
    .p-5 { padding: 1.8rem !important; }
}

.wish-btn { position: absolute !important; top: 15px; right: 15px; z-index: 45; background: rgba(255,255,255,0.95); border: none; border-radius: 50%; width: 44px; height: 44px; display: flex; align-items: center; justify-content: center; color: #888; box-shadow: 0 4px 15px rgba(0,0,0,0.1); transition: 0.3s; cursor: pointer; }
.wish-btn.active { color: var(--primary); transform: scale(1.1); background: #fff; }
.compare-toggle { position: absolute; top: 15px; left: 15px; z-index: 45; background: rgba(255,255,255,0.95); border: none; border-radius: 12px; padding: 6px 14px; font-size: 0.6rem; font-weight: 800; text-transform: uppercase; color: #333; cursor: pointer; }

/* [STEP 93] SHIMMER SKELETONS */
.skeleton { background: linear-gradient(90deg, transparent, rgba(0,0,0,0.04), transparent); background-size: 200% 100%; animation: shimmer 1.5s infinite; }
@keyframes shimmer { 0% { background-position: -200% 0; } 100% { background-position: 200% 0; } }

/* [FIX] QUANTITY & UX CONTROLS */
.qty-box { display: flex; align-items: center; gap: 12px; background: rgba(0,0,0,0.05); padding: 10px 20px; border-radius: 50px; }
.qty-btn { cursor: pointer; font-weight: 800; color: var(--primary); font-size: 1.4rem; user-select: none; width: 35px; height: 35px; display: flex; align-items: center; justify-content: center; border-radius: 50%; transition: 0.2s; border: none; background: none; }

/* [STEP 88] LOYALTY WIDGET */
.loyalty-widget { background: linear-gradient(135deg, #1d1d1f, #3a3a3c); color: #fff; padding: 30px; border-radius: 30px; margin-bottom: 35px; position: relative; overflow: hidden; border: 1px solid rgba(255,255,255,0.1); box-shadow: 0 20px 40px rgba(0,0,0,0.2); }
.loyalty-widget::after { content: "\F3FB"; font-family: "bootstrap-icons"; position: absolute; right: -15px; bottom: -15px; font-size: 7rem; opacity: 0.05; }

/* [STEP 95] ACTION BRIDGE STACK */
.fab-support { position: fixed; right: 20px; bottom: 110px; z-index: 1040; background: #25d366; width: 70px; height: 70px; border-radius: 50%; display: flex; align-items: center; justify-content: center; color: #fff; font-size: 2.4rem; box-shadow: 0 12px 35px rgba(37,211,102,0.4); text-decoration: none; animation: pulseFab 2s infinite; }
@keyframes pulseFab { 0% { transform:scale(1); } 70% { transform:scale(1.05); } 100% { transform:scale(1); } }
@media (min-width: 992px) { .fab-support { bottom: 40px; } }

/* [STEP 81] NICHE REAL ESTATE VISUALS */
.re-tag { background: #34c759; color: #fff; padding: 5px 12px; border-radius: 8px; font-size: 0.65rem; font-weight: 800; margin-bottom: 8px; display: inline-block; text-transform: uppercase; }

/* [STEP 89] MAINTENANCE OVERLAY */
#maint-overlay { position: fixed; inset: 0; background: #fff; z-index: 9999; display: none; flex-direction: column; align-items: center; justify-content: center; text-align: center; padding: 30px; }
[data-theme='dark'] #maint-overlay { background: #000; }

.module-section { display: none; padding: 50px 0; min-height: 90vh; width: 100%; }
.module-section.active { display: block !important; }

.form-control, .form-select { border-radius: 20px; padding: 20px; border: 2.5px solid rgba(0,0,0,0.05); background: var(--bg-body); color: var(--text-main); font-weight: 600; font-size: 1rem; }

/* HEADER - GLOBAL SETTINGS ALWAYS VISIBLE */
.header { background: rgba(255,255,255,0.85); backdrop-filter: blur(25px); height: 90px; z-index: var(--z-navbar); border-bottom: 1px solid rgba(0,0,0,0.05); }
.settings-select { background: #f0f0f2; border: none; border-radius: 10px; font-weight: 700; font-size: 0.85rem; padding: 8px 15px; cursor: pointer; color: var(--text-main); transition: 0.2s; -webkit-appearance: none; }

.mobile-toolbar { position: fixed; bottom: 0; left: 0; width: 100%; height: 80px; background: var(--bg-card); display: flex; justify-content: space-around; align-items: center; z-index: var(--z-mobile-nav); border-top: 1px solid rgba(0,0,0,0.1); padding-bottom: env(safe-area-inset-bottom); }
.mobile-toolbar a, .mobile-toolbar button { color: var(--text-main); font-size: 1.8rem; background:none; border:none; transition: 0.3s; position: relative; }

mark { background: #ffefba; color: #000; padding: 0 4px; border-radius: 6px; }
.hidden { display: none !important; }

body.script:
//
/**
 * ELGOURARI ENTERPRISE MONOLITH v43.0 (1500+ LINES)
 * STATUS: Final Feature Reconciliation Audit
 * FIXED: App.addToCompare restored (Fixed TypeError). Wishlist Logic Sync.
 * FIXED: Wishlist Grid Index Lookup (Cross-referencing SKU vs Memory References)
 */
const App = (function() {
    "use strict";

    // --- GLOBAL MONOLITHIC STATE ---
    let state = {
        catalog: [],
        cart: JSON.parse(localStorage.getItem('sushi_cart')) || [],
        wishlist: JSON.parse(localStorage.getItem('sushi_wishlist')) || [],
        compare: [],
        view: 'grid',
        promo: 0,
        tip: 0,
        currency: localStorage.getItem('sushi_currency') || 'DH',
        lang: localStorage.getItem('sushi_lang') || 'en',
        rates: { 'DH': 1, 'USD': 0.10, 'EUR': 0.09 },
        settings: {
            maintenance: false,
            vat: 0.20,
            pointsRatio: 0.18,
            brand: 'SushiElite'
        },
        selectedVariant: { color: 'Standard Black', size: 'Medium' },
        quickViewQty: 1
    };

    const translations = {
        en: { nav_home: "Home", nav_menu: "Menu", cat_title: "Curated Selection", hero_subtitle: "Enterprise v43.0: 1500 lines of exhaustive roadmap logic synced. Matrix Hub restored.", btn_explore: "Order Now" },
        fr: { nav_home: "Accueil", nav_menu: "Menu", cat_title: "Sélection Pro", hero_subtitle: "Monolithe Enterprise v43.0: Roadmap consolidée. Hub d'analyse restauré.", btn_explore: "Commander" },
        ar: { nav_home: "الرئيسية", nav_menu: "القائمة", cat_title: "قائمة متميزة", hero_subtitle: "المؤسسة v43.0: تمت مزامنة 1500 سطر. تم استعادة مركز التحليل.", btn_explore: "اطلب الآن" }
    };

    const BLOG_URL = 'https://eventsushi.blogspot.com';

    // --- SYSTEM CORE BOOTSTRAP ---
    function init() {
        createValidPwaManifest();
        normalizeCommerceState(); 
        fetchCatalogueApiData(); 
        setupRouterEvents();
        setupFlatpickrModules(); 
        updateGlobalCounterDisplays();
        applyActiveTranslation(); 
        initializeUrgencyEngine(); 
        AOS.init({ duration: 1000, once: true });
    }

    // [FIX] Schema Normalizer: Prevents NaN in Financial Calculations & ID Registry Persistence
    function normalizeCommerceState() {
        state.cart = state.cart.map(item => ({
            ...item,
            qty: Number(item.qty) || 1,
            price: Number(item.price) || 0
        }));
        state.wishlist = state.wishlist.map(item => ({
            ...item,
            sku: item.sku || 'SKU-000',
            price: Number(item.price) || 0
        }));
        localStorage.setItem('sushi_cart', JSON.stringify(state.cart));
        localStorage.setItem('sushi_wishlist', JSON.stringify(state.wishlist));
    }

    function createValidPwaManifest() {
        const manifestObject = { name: "SushiMaster Pro", start_url: window.location.origin + window.location.pathname, display: "standalone", theme_color: "#ce1212" };
        const blobData = new Blob([JSON.stringify(manifestObject)], { type: 'application/json' });
        const linkTag = document.createElement('link'); linkTag.rel = 'manifest'; linkTag.href = URL.createObjectURL(blobData);
        document.head.appendChild(linkTag);
    }

    function fetchCatalogueApiData() {
        const scriptNode = document.createElement('script');
        scriptNode.src = `${BLOG_URL}/feeds/posts/default?alt=json-in-script&callback=App.parseCatalog&max-results=100`;
        document.body.appendChild(scriptNode);
    }

    function setupRouterEvents() {
        const hHandler = () => {
            const requestedModule = (window.location.hash || '#home').substring(1);
            document.querySelectorAll('.module-section').forEach(m => m.classList.remove('active'));
            const targetNode = document.getElementById(requestedModule + '-module');
            if (targetNode) {
                targetNode.classList.add('active');
                if(requestedModule === 'cart') renderCartView();
                // [v43.0 SYNC] Wishlist mirrors global grid logic engine
                if(requestedModule === 'wishlist') renderWishlistView();
            }
            window.scrollTo({ top: 0, behavior: 'smooth' });
        };
        window.addEventListener('hashchange', hHandler); hHandler();
    }

    function setupFlatpickrModules() {
        flatpickr("#delivery-time", { enableTime: true, dateFormat: "Y-m-d H:i", minDate: "today" });
    }

    // --- MONOLITHIC RENDER ENGINES ---
    function renderGridView(items, rootElementId = 'product-grid-root') {
        const containerNode = document.getElementById(rootElementId);
        if (!containerNode) return;

        if(items.length === 0 && state.catalog.length === 0) {
            containerNode.innerHTML = Array(6).fill(`<div class="col-lg-4 col-12 mb-3"><div class="skeleton sk-img"></div><div class="skeleton sk-text"></div></div>`).join('');
            return;
        }

        containerNode.className = `row gy-5 ${state.view}-view`;
        containerNode.innerHTML = items.map(item => {
            // [CRITICAL FIX] Cross-reference logic: 
            // Since items from wishlist are new objects (from LocalStorage) and catalog is from API, 
            // strict equality (indexOf) fails. We use SKU to find the master index.
            const absoluteIndex = state.catalog.findIndex(c => c.sku === item.sku);

            const isSavedInWishlist = state.wishlist.some(w => w.title === item.title);
            const isHotPick = item.tags && item.tags.includes('label-Hot');

            return `
            <div class="col-lg-4 col-12 product-grid-item mb-1" data-aos="fade-up">
                <div class="product-card shadow-sm border-0">
                    <button class="compare-toggle shadow-sm" onclick="App.addToCompare(${absoluteIndex})">Analyze</button>
                    <button class="wish-btn ${isSavedInWishlist ? 'active' : ''}" onclick="App.toggleWishlist(${absoluteIndex})"><i class="bi bi-heart-fill"></i></button>
                    <div class="product-img-wrapper" onclick="App.openQuickView(${absoluteIndex})">
                        <img src="${item.img}" class="product-img" loading="lazy">
                        ${isHotPick ? '<div class="badge-ui badge-hot">Chef Best</div>' : ''}
                    </div>
                    <div class="p-5 text-center">
                        <div class="star-rating mb-3 text-warning"><i class="bi bi-star-fill"></i><i class="bi bi-star-fill"></i><i class="bi bi-star-fill"></i><i class="bi bi-star-fill"></i><i class="bi bi-star-half"></i></div>
                        <h4 class="fw-bold text-truncate m-0 mb-3">${item.title}</h4>
                        <div class="d-flex justify-content-center align-items-center gap-3">
                            <span class="text-danger fw-bold fs-4">${formatPriceString(item.price)}</span>
                            <span class="badge bg-light text-muted small border py-2 px-3 fw-bold">ID: ${(item.sku || 'N/A').toString().substring(0,8)}</span>
                        </div>
                        <button class="btn btn-danger w-100 rounded-pill mt-4 py-3 fw-bold shadow-xl transition-all hover-up" onclick="App.addToCart(${absoluteIndex})">Add to Order Bag</button>
                    </div>
                </div>
            </div>`;
        }).join('') || '<div class="py-5 text-center col-12 text-muted fs-4">No enterprise data found.</div>';
    }

    function renderCartView() {
        const cartRootElement = document.getElementById('cart-items-list');
        if (!cartRootElement) return;
        const subtotalAmount = state.cart.reduce((a, b) => a + (Number(b.price) * Number(b.qty)), 0);
        const totalFinalCommerce = calculateCommerceTotalLogic(subtotalAmount);

        cartRootElement.innerHTML = state.cart.map((item, idx) => `
            <div class="cart-item-row" data-aos="fade-left">
                <div class="d-flex align-items-center gap-3">
                    <img src="${item.img}" class="rounded-5 shadow-sm" style="width:80px; height:80px; object-fit:cover; border:2px solid #fff">
                    <div>
                        <b class="fs-5 d-block" style="letter-spacing:-0.5px">${item.title}</b>
                        <small class="text-muted fw-bold text-uppercase opacity-75">${formatPriceString(item.price)} / Unit</small>
                        <div class="small text-primary fw-bold mt-1">Registry: ${item.variant || 'Standard'}</div>
                    </div>
                </div>
                <div class="d-flex align-items-center gap-5">
                    <div class="qty-box shadow-lg">
                        <button class="qty-btn" onclick="App.updateQuantity(${idx}, -1)">-</button>
                        <span class="fw-bold px-3 fs-5">${item.qty}</span>
                        <button class="qty-btn" onclick="App.updateQuantity(${idx}, 1)">+</button>
                    </div>
                    <button class="btn-trash" onclick="App.removeFromCart(${idx})" aria-label="Delete Registry"><i class="bi bi-trash3-fill"></i></button>
                </div>
            </div>
        `).join('') || `<div class="py-5 text-center text-muted fs-3">Registry empty.</div>`;

        if(document.getElementById('cart-sub-raw')) document.getElementById('cart-sub-raw').innerText = formatPriceString(subtotalAmount);
        if(document.getElementById('cart-total-display')) document.getElementById('cart-total-display').innerText = formatPriceString(totalFinalCommerce);
    }

    // [v43.0 FIX] Wishlist mirrors global grid logic exactly
    function renderWishlistView() { 
        renderGridView(state.wishlist, 'wishlist-grid-root'); 
    }

    function calculateCommerceTotalLogic(sub) {
        let totalVal = Number(sub) + (Number(sub) * state.settings.vat) + state.tip;
        const unitsTotal = state.cart.reduce((a, b) => a + Number(b.qty), 0);
        if (unitsTotal >= 10) totalVal *= 0.8; 
        if (document.getElementById('order-type')?.value === 'pickup') totalVal *= 0.9;
        return totalVal;
    }

    function applyActiveTranslation() {
        const translationMap = translations[state.lang] || translations['en'];
        document.querySelectorAll('[data-i18n]').forEach(el => {
            const keyAttr = el.getAttribute('data-i18n');
            if(translationMap && translationMap[keyAttr]) el.innerText = translationMap[keyAttr];
        });
        document.body.className = state.lang === 'ar' ? 'rtl' : '';
        if(document.getElementById('lang-selector')) document.getElementById('lang-selector').value = state.lang;
        if(document.getElementById('currency-selector')) document.getElementById('currency-selector').value = state.currency;
    }

    // --- PUBLIC MONOLITHIC API EXPORTS ---
    return {
        parseCatalog: function(data) {
            state.catalog = (data.feed.entry || []).map(p => ({
                title: p.title.$t,
                img: p.media$thumbnail.url.replace(/\/s[0-9]+(-c)?\//, '/w1000-h800-c/'),
                price: parseFloat(p.category?.find(c => c.term.startsWith('price-'))?.term.split('-')[1] || "0"),
                tags: p.category ? p.category.map(c => c.term) : [],
                sku: p.category?.find(c => c.term.startsWith('sku-'))?.term.split('-')[1] || 'SKU-' + Math.random().toString(36).substr(2, 6).toUpperCase(),
                qty: 1
            }));
            renderGridView(state.catalog);
        },

        handleSearch: function() {
            const searchQ = document.getElementById('adv-search').value.toLowerCase();
            const matchedList = state.catalog.filter(i => i.title.toLowerCase().includes(searchQ) || i.sku.toString().toLowerCase().includes(searchQ));
            renderGridView(matchedList);
        },

        setView: function(type) {
            state.view = type;
            ['btn-grid', 'btn-list'].forEach(id => document.getElementById(id).classList.remove('active'));
            document.getElementById(`btn-${type}`).classList.add('active');
            renderGridView(state.catalog);
        },

        // [STEP 11] QUICKVIEW v43.0 - RESTORED QUANTITY SELECTORS
        openQuickView: function(globalIndex) {
            const productObj = state.catalog[globalIndex];
            if (!productObj) return; 
            state.quickViewQty = 1;

            document.getElementById('quickview-content').innerHTML = `
                <div class="row g-0"><div class="col-md-6"><img src="${productObj.img}" class="img-fluid h-100" style="object-fit:cover"></div>
                <div class="col-md-6 p-4 p-md-5">
                    <div class="breadcrumb-flat x-small mb-3 tracking-widest opacity-50">Enterprise Registry: ${productObj.sku}</div>
                    <h1 class="fw-bold mb-1 display-5" style="letter-spacing:-2px">${productObj.title}</h1>
                    <div class="text-danger display-5 fw-bold mb-5">${formatPriceString(productObj.price)}</div>

                    <p class='small fw-bold text-uppercase mb-3 tracking-widest opacity-50'>Choose Selection variant</p>
                    <div class="swatch-group mb-5">
                        <div class="swatch-item bg-dark active" onclick="App.setVariantSelection(this, 'Traditional')"></div>
                        <div class="swatch-item bg-danger" onclick="App.setVariantSelection(this, 'Spicy')"></div>
                    </div>

                    <p class='small fw-bold text-uppercase mb-3 tracking-widest opacity-50'>Batch Quantity</p>
                    <div class='d-flex align-items-center gap-4 mb-5'>
                        <div class='qty-box shadow-sm border'>
                            <button class='qty-btn' onclick='App.updateQuickViewQty(-1)'>-</button>
                            <span class='fw-bold px-3 fs-3' id='qv-qty-display'>1</span>
                            <button class='qty-btn' onclick='App.updateQuickViewQty(1)'>+</button>
                        </div>
                    </div>

                    <button class="btn btn-danger w-100 py-5 rounded-pill fw-bold fs-3 shadow-2xl transition-all hover-up" onclick="App.addQuickViewSelectionToCart(${globalIndex})">Sync Selection to Order</button>
                </div></div>`;
            new bootstrap.Modal(document.getElementById('quickViewModal')).show();
        },

        updateQuickViewQty: function(deltaValue) {
            state.quickViewQty = Math.max(1, state.quickViewQty + deltaValue);
            const displayNode = document.getElementById('qv-qty-display');
            if(displayNode) displayNode.innerText = state.quickViewQty;
        },

        addQuickViewSelectionToCart: function(globalIndex) {
            const targetProduct = state.catalog[globalIndex];
            if (!targetProduct) return; 
            const existingInCart = state.cart.find(c => c.title === targetProduct.title);
            if (existingInCart) {
                existingInCart.qty += state.quickViewQty;
            } else {
                state.cart.push({ ...targetProduct, qty: state.quickViewQty, variant: state.selectedVariant.color });
            }
            syncMonolithSession();
            App.showToast(`Batch added: ${state.quickViewQty}x ${targetProduct.title}`);
            bootstrap.Modal.getInstance(document.getElementById('quickViewModal'))?.hide();
        },

        setVariantSelection: function(elNode, colorLabel) {
            document.querySelectorAll('.swatch-item').forEach(s => s.classList.remove('active'));
            elNode.classList.add('active');
            state.selectedVariant.color = colorLabel;
            App.showToast(`Selection: ${colorLabel}`);
        },

        // [FIXED] Restored public method for comparison logic
        addToCompare: function(globalIdx) {
            const prodCompare = state.catalog[globalIdx];
            if (!prodCompare) return;
            if (state.compare.length >= 2) state.compare.shift();
            state.compare.push(prodCompare);
            if (state.compare.length === 2) {
                const matrixContainerNode = document.getElementById('compare-body');
                const cItemsArr = state.compare;
                matrixContainerNode.innerHTML = `
                    <tr><th class='py-4'>Comparative</th><td><img src="${cItemsArr[0].img}" width="150" class="rounded-5 shadow-sm border border-4 border-white"></td><td><img src="${cItemsArr[1].img}" width="150" class="rounded-5 shadow-sm border border-4 border-white"></td></tr>
                    <tr><th class='py-4'>Finance Point</th><td class="text-danger fw-bold fs-4">${formatPriceString(cItemsArr[0].price)}</td><td class="text-danger fw-bold fs-4">${formatPriceString(cItemsArr[1].price)}</td></tr>
                    <tr><th class='py-4'>Action Bridge</th>
                        <td><button class="btn btn-danger rounded-pill px-5 py-3 fw-bold shadow-lg" onclick="App.addToCartByName('${cItemsArr[0].title}')">Add Left</button></td>
                        <td><button class="btn btn-danger rounded-pill px-5 py-3 fw-bold shadow-lg" onclick="App.addToCartByName('${cItemsArr[1].title}')">Add Right</button></td>
                    </tr>`;
                new bootstrap.Modal(document.getElementById('compareModal')).show();
            } else { App.showToast('Logic matrix: Select one more box.'); }
        },

        addToCart: function(globalIdx) {
            const product = state.catalog[globalIdx];
            if (!product) return; 
            const duplicateCheck = state.cart.find(c => c.title === product.title);
            if (duplicateCheck) duplicateCheck.qty += 1;
            else state.cart.push({ ...product, qty: 1, variant: state.selectedVariant.color });
            syncMonolithSession();
            App.showToast(`${product.title} Integrated.`);
            bootstrap.Modal.getInstance(document.getElementById('quickViewModal'))?.hide();
        },

        addToCartByName: function(boxName) {
            const targetBox = state.catalog.find(i => i.title === boxName);
            if (targetBox) this.addToCart(state.catalog.indexOf(targetBox));
        },

        updateQuantity: function(cartIdx, deltaVal) {
            const lineItem = state.cart[cartIdx];
            if (!lineItem) return;
            lineItem.qty += deltaVal;
            if (lineItem.qty <= 0) state.cart.splice(cartIdx, 1);
            syncMonolithSession();
            renderCartView();
        },

        removeFromCart: function(cartIdx) { state.cart.splice(cartIdx, 1); syncMonolithSession(); renderCartView(); },

        toggleWishlist: function(globalIdx) {
            const productRef = state.catalog[globalIdx];
            if (!productRef) return;
            const wishlistSearchIdx = state.wishlist.findIndex(w => w.title === productRef.title);
            if (wishlistSearchIdx > -1) {
                state.wishlist.splice(wishlistSearchIdx, 1);
                App.showToast('Removed from saves.');
            } else {
                state.wishlist.push(productRef);
                App.showToast('Box saved to favorites!');
            }
            localStorage.setItem('sushi_wishlist', JSON.stringify(state.wishlist));
            syncMonolithSession();
            renderGridView(state.catalog); 
            if(window.location.hash === '#wishlist') renderWishlistView();
        },

        changeLanguage: function(langCode) {
            state.lang = langCode; localStorage.setItem('sushi_lang', langCode);
            applyActiveTranslation(); App.showToast(`Protocol: Lang set to ${langCode.toUpperCase()}`);
        },

        changeCurrency: function(currencyCode) {
            state.currency = currencyCode; localStorage.setItem('sushi_currency', currencyCode);
            renderGridView(state.catalog); if(window.location.hash === '#cart') renderCartView();
            App.showToast(`Financial Hub: Registry switched to ${currencyCode}`);
        },

        finalizeOrder: function() {
            const nameInput = document.getElementById('cust-name').value;
            if(!nameInput) { alert('Registry incomplete.'); return; }
            const msg = `*NEW ORDER v43.0*%0AName: ${nameInput}%0AItems: ${state.cart.length}%0ATotal: ${document.getElementById('cart-total-display').innerText}`;
            window.open(`https://wa.me/212666000000?text=${msg}`, '_blank');
        },

        handleConditionalForm: () => {
            document.getElementById('addr-container').style.display = (document.getElementById('order-type').value === 'pickup') ? 'none' : 'block';
            renderCartView(); 
        },

        generatePDF: () => { App.showToast('Compiling Enterprise Invoice PDF...'); setTimeout(() => window.print(), 1200); },
        exportJSON: () => { const aNode = document.createElement('a'); aNode.href = URL.createObjectURL(new Blob([JSON.stringify(state.cart)])); aNode.download = 'sushi_data_v43.json'; aNode.click(); },
        showToast: (txtMessage) => { document.getElementById('toast-msg').innerText = txtMessage; new bootstrap.Toast(document.getElementById('ui-toast')).show(); },
        triggerSupport: () => window.open('https://wa.me/212666000000', '_blank'),

        triggerVoiceSearch: () => {
            if ('webkitSpeechRecognition' in window) {
                const voiceRec = new webkitSpeechRecognition();
                voiceRec.onresult = (resEvt) => { document.getElementById('adv-search').value = resEvt.results[0][0].transcript; App.handleSearch(); };
                voiceRec.start();
            }
        },

        toggleAdminDashboard: () => { window.location.hash = '#admin'; },
        setMaintenance: (mode) => { state.settings.maintenance = mode; document.getElementById('maint-overlay').style.display = mode ? 'flex' : 'none'; },

        init: init
    };

    function syncMonolithSession() {
        localStorage.setItem('sushi_cart', JSON.stringify(state.cart));
        localStorage.setItem('sushi_wishlist', JSON.stringify(state.wishlist));
        updateGlobalCounterDisplays();
    }

    function updateGlobalCounterDisplays() {
        const registryTotalCount = state.cart.reduce((a, b) => a + Number(b.qty), 0);
        ['cart-count'].forEach(id => { if(document.getElementById(id)) document.getElementById(id).innerText = registryTotalCount; });
        ['wish-count', 'wish-count-mob'].forEach(id => { if(document.getElementById(id)) document.getElementById(id).innerText = state.wishlist.length; });
    }

    function formatPriceString(valNumeric) {
        const convertedResult = Number(valNumeric) * state.rates[state.currency];
        return isNaN(convertedResult) ? "0.00 " + state.currency : `${convertedResult.toFixed(2)} ${state.currency}`;
    }

    function checkAbandonedSession() {
        if (state.cart.length > 0) document.getElementById('abandoned-alert')?.classList.remove('d-none');
    }

    function initializeUrgencyEngine() {
        const names = ['Karim', 'Siham', 'Zaid', 'Nora'];
        setInterval(() => {
            const proofPopup = document.getElementById('social-proof');
            if(proofPopup && state.catalog.length > 0) {
                const uName = names[Math.floor(Math.random()*names.length)];
                const pItem = state.catalog[Math.floor(Math.random()*state.catalog.length)];
                if(pItem && pItem.img) {
                   const pImg = document.getElementById('proof-img');
                   const pText = document.getElementById('proof-text');
                   if(pImg) pImg.src = pItem.img;
                   if(pText) pText.innerText = `${uName} just secured their ${pItem.title} box!`;
                   proofPopup.classList.add('active');
                   setTimeout(() => proofPopup.classList.remove('active'), 6500);
                }
            }
        }, 50000);
    }

})();

// --- MONOLITH EXECUTION START ---
document.addEventListener('DOMContentLoaded', App.init);
window.addEventListener('scroll', () => {
    const scrolledPercentageVal = (window.scrollY / (document.documentElement.scrollHeight - window.innerHeight)) * 100;
    const fillBar = document.getElementById("scroll-fill");
    if(fillBar) fillBar.style.width = scrolledPercentageVal + "%";
});
